const b = $json.body ?? $json;
const required = ['channel','message_id','guest_name','phone','check_in','check_out','adults'];
for (const key of required) { if (b[key] === undefined || b[key] === null || String(b[key]).trim() === '') throw new Error(`Missing required field: ${key}`); }
const channel = String(b.channel).trim().toUpperCase();
const messageId = String(b.message_id).trim();
return [{ json: { channel, message_id: messageId, idempotency_key: `${channel}:${messageId}`, guest_name: String(b.guest_name).trim(), phone: String(b.phone).trim(), email: b.email || null, check_in: String(b.check_in), check_out: String(b.check_out), adults: Number(b.adults), children: Number(b.children || 0), room_type_code: b.room_type_code || null, notes: b.notes || null, conversation_id: b.conversation_id || null } }];

const requestResult = $('Create Reservation Request').item.json;
const availability = $('Check Availability').item.json;
if (requestResult.is_reservation !== false) throw new Error('Core contract violation: automation must not create a guaranteed reservation');
const expectedLink = Boolean($('Normalize Intake').item.json.conversation_id);
if (expectedLink && requestResult.conversation_linked !== true) throw new Error('Core contract violation: hot lead was not linked to its inbox conversation');
return [{ json: { ok: true, reservation_request: requestResult, availability, truth: 'REQUEST_CREATED_NOT_CONFIRMED_RESERVATION' } }];
